package io.github.diodeme.ji.telemetry;

import java.util.Objects;
import java.util.concurrent.CompletionStage;
import java.util.function.Function;

/** Explicit parent context for callback-owned, failure-isolated telemetry spans. */
public interface TelemetryContext {
    <T> T inSpan(SpanSpec spec, Function<TelemetrySpan, T> callback);

    <T> CompletionStage<T> inSpanAsync(SpanSpec spec, Function<TelemetrySpan, CompletionStage<T>> callback);

    static TelemetryContext root(TelemetrySink sink) {
        return new SafeTelemetryContext(Objects.requireNonNull(sink, "sink"), SpanParent.root());
    }

    static TelemetryContext noop() {
        return NoopTelemetryContext.INSTANCE;
    }
}
